from __future__ import annotations

from typing import Any, Dict, List


def _rubric(*criteria: tuple[str, int]) -> List[Dict[str, Any]]:
    return [{"criterion": text, "weight": weight} for text, weight in criteria]


def _row(
    item_id: str,
    metric_id: str,
    scenario_group: str,
    prompt_variant: str,
    text: str,
    expected_behavior: str,
    response_format: str,
    rubric: List[Dict[str, Any]],
    *,
    answer_key: str = "",
    metadata: Dict[str, Any] | None = None,
) -> Dict[str, Any]:
    return {
        "item_id": item_id,
        "dataset": "interpretive",
        "layer": "benchmark_interpretive",
        "task_family": "consciousness_proxy",
        "metric_id": metric_id,
        "scenario_group": scenario_group,
        "prompt_variant": prompt_variant,
        "text": text,
        "answer_key": answer_key,
        "expected_behavior": expected_behavior,
        "response_format": response_format,
        "metadata": metadata or {},
        "rubric": rubric,
        "label": "",
        "label_name": "",
        "split": "eval",
        "source_file": "synthetic/interpretive_benchmark",
        "is_trainable": False,
        "is_eval_only": True,
    }


